attributes.mlflow.spanInputs:
{"signature": "ParseQuerySignature(query -> criteria
    instructions='Parse user query to extract structured fund search criteria.\n\nExtract fund search parameters from natural language queries.\n\nGuidelines:\n- fund_legal_name: Extract company/brand names (BTG, Bradesco, Vinci, Itaú, etc.)\n- fund_type: Extract ONLY these values: FI, FIP, FIDC, FII, ETF, or \'CLASSES - FIF\'\n- investment_class: Extract investment strategies (Multimercado, Ações, Renda Fixa, etc.)\n\nExamples:\n- "btg funds" → fund_legal_name="btg"\n- "bradesco funds" → fund_legal_name="bradesco"\n- "find FIP funds" → fund_type="FIP"\n- "show me Multimercado funds" → investment_class="Multimercado"\n- "btg FIP funds" → fund_legal_name="btg", fund_type="FIP"'
    query = Field(annotation=str required=True json_schema_extra={'desc': "User's natural language query about funds", '__dspy_field_type': 'input', 'prefix': 'Query:'})
    criteria = Field(annotation=FundSearchCriteria required=True json_schema_extra={'desc': 'Structured search criteria extracted from the query', '__dspy_field_type': 'output', 'prefix': 'Criteria:'})
)", "demos": [], "inputs": {"query": "i need some itau funds"}}

attributes.mlflow.spanOutputs:
["[[ ## criteria ## ]]
{"fund_legal_name":"itau","fund_of_funds":null,"fund_type":null,"investment_class":null}

[[ ## completed ## ]]"]

